--
-- Table structure for table `user_bonuses`
--

DROP TABLE IF EXISTS `user_bonuses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_bonuses` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `bonus_id` bigint unsigned DEFAULT NULL,
  `amount` decimal(18,2) NOT NULL,
  `wagering_required` decimal(18,2) DEFAULT '0.00',
  `wagering_completed` decimal(18,2) DEFAULT '0.00',
  `credit_target` enum('bonus','main') COLLATE utf8mb4_unicode_ci DEFAULT 'bonus',
  `source` enum('joining','deposit','referral','game','cashback','promo','manual') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `transaction_id` bigint unsigned DEFAULT NULL,
  `granted_by` bigint unsigned DEFAULT NULL,
  `notes` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','completed','expired','forfeited') COLLATE utf8mb4_unicode_ci DEFAULT 'active',
